/**
 * Writes src/lib/units/index.generated.ts: the dictionary words and ids of the hand-written units.
 * The app imports this small file instead of the full lesson texts. Run after editing any unit:
 *   npx tsx scripts/emit-unit-index.ts
 */
import { writeFileSync } from 'node:fs'
import { UNIT_SPECS, UNIT_VOCABULARY_SOURCE } from '../src/lib/units/specs'

export function unitIndexSource(): string {
  return [
    '// Generated by scripts/emit-unit-index.ts. Do not edit by hand.',
    "import type { VocabularyWord } from '@/lib/course'",
    '',
    '/** Units whose lesson is hand-written. */',
    `export const HAND_WRITTEN_UNIT_IDS: string[] = ${JSON.stringify(UNIT_SPECS.map((spec) => spec.id), null, 2)}`,
    '',
    '/** Modules that are fully hand-written (no "Draft" label). Module 1 was written by hand before the unit kit. */',
    'export const REWRITTEN_MODULE_ORDERS = new Set<number>([1])',
    '',
    `export const UNIT_VOCABULARY: VocabularyWord[] = ${JSON.stringify(UNIT_VOCABULARY_SOURCE, null, 1)}`,
    '',
  ].join('\n')
}

if (process.argv[1]?.endsWith('emit-unit-index.ts')) {
  writeFileSync('src/lib/units/index.generated.ts', unitIndexSource())
  console.log(`emit-unit-index: ${UNIT_SPECS.length} units, ${UNIT_VOCABULARY_SOURCE.length} words`)
}
